    <script>
        /* Complete JavaScript - ALL functionality inline, no external files */

        // Configuration
        const API_BASE_URL = window.location.origin;
        const CACHE_TTL = 300000; // 5 minutes

        // State management
        const state = {
            currentPage: 'search',
            query: '',
            filters: {
                domains: [],
                dateStart: null,
                dateEnd: null,
                numResults: 10
            },
            results: [],
            cache: new Map(),
            apiKey: localStorage.getItem('apiKey') || '',
            adminApiKey: localStorage.getItem('adminApiKey') || '',
            isAuthenticated: false,
            theme: localStorage.getItem('theme') || 'light'
        };

        // DOM elements
        const elements = {
            searchInput: document.getElementById('searchInput'),
            searchButton: document.getElementById('searchButton'),
            resultsContainer: document.getElementById('resultsContainer'),
            domainFilter: document.getElementById('domainFilter'),
            dateFrom: document.getElementById('dateFrom'),
            dateTo: document.getElementById('dateTo'),
            numResults: document.getElementById('numResults'),
            resetFilters: document.getElementById('resetFilters'),
            applyFilters: document.getElementById('applyFilters'),
            themeToggle: document.getElementById('themeToggle'),
            endpointSelect: document.getElementById('endpointSelect'),
            requestBody: document.getElementById('requestBody'),
            sendRequest: document.getElementById('sendRequest'),
            responseStatus: document.getElementById('responseStatus'),
            responseBody: document.getElementById('responseBody'),
            adminApiKey: document.getElementById('adminApiKey'),
            loginButton: document.getElementById('loginButton'),
            adminLogin: document.getElementById('adminLogin'),
            adminDashboard: document.getElementById('adminDashboard'),
            crawlUrls: document.getElementById('crawlUrls'),
            crawlDepth: document.getElementById('crawlDepth'),
            submitCrawl: document.getElementById('submitCrawl'),
            jobsTableBody: document.getElementById('jobsTableBody'),
            modal: document.getElementById('modal'),
            modalClose: document.getElementById('modalClose'),
            modalTitle: document.getElementById('modalTitle'),
            modalBody: document.getElementById('modalBody')
        };

        // Utility functions
        function debounce(func, wait) {
            let timeout;
            return function executedFunction(...args) {
                const later = () => {
                    clearTimeout(timeout);
                    func(...args);
                };
                clearTimeout(timeout);
                timeout = setTimeout(later, wait);
            };
        }

        function formatDate(dateString) {
            const date = new Date(dateString);
            const now = new Date();
            const diffTime = Math.abs(now - date);
            const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

            if (diffDays === 0) return 'Today';
            if (diffDays === 1) return 'Yesterday';
            if (diffDays < 7) return `${diffDays} days ago`;
            if (diffDays < 30) return `${Math.floor(diffDays / 7)} weeks ago`;
            if (diffDays < 365) return `${Math.floor(diffDays / 30)} months ago`;
            return `${Math.floor(diffDays / 365)} years ago`;
        }

        function highlightText(text, query) {
            if (!query) return text;
            const terms = query.toLowerCase().split(' ');
            let highlighted = text;
            terms.forEach(term => {
                const regex = new RegExp(`(${term})`, 'gi');
                highlighted = highlighted.replace(regex, '<mark>$1</mark>');
            });
            return highlighted;
        }

        function getCacheKey(query, filters) {
            return JSON.stringify({ query, filters });
        }

        function getFromCache(key) {
            const cached = state.cache.get(key);
            if (!cached) return null;
            if (Date.now() - cached.timestamp > CACHE_TTL) {
                state.cache.delete(key);
                return null;
            }
            return cached.data;
        }

        function setCache(key, data) {
            state.cache.set(key, {
                data: data,
                timestamp: Date.now()
            });
        }

        // API functions
        async function apiRequest(endpoint, options = {}) {
            const headers = {
                'Content-Type': 'application/json',
                ...options.headers
            };

            if (state.apiKey) {
                headers['X-API-Key'] = state.apiKey;
            }

            const response = await fetch(`${API_BASE_URL}${endpoint}`, {
                ...options,
                headers
            });

            if (!response.ok) {
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            }

            return await response.json();
        }

        async function search(query, filters = {}) {
            const startTime = Date.now();
            const cacheKey = getCacheKey(query, filters);

            // Check cache
            const cached = getFromCache(cacheKey);
            if (cached) {
                console.log('Using cached results');
                return cached;
            }

            // Prepare request
            const payload = {
                query: query,
                num_results: filters.numResults || 10
            };

            if (filters.domains && filters.domains.length > 0) {
                payload.domains = filters.domains;
            }

            if (filters.dateStart) {
                payload.date_start = new Date(filters.dateStart).toISOString();
            }

            if (filters.dateEnd) {
                payload.date_end = new Date(filters.dateEnd).toISOString();
            }

            // Make request
            const data = await apiRequest('/api/search', {
                method: 'POST',
                body: JSON.stringify(payload)
            });

            // Cache result
            setCache(cacheKey, data);

            console.log(`Search completed in ${Date.now() - startTime}ms`);
            return data;
        }

        // UI rendering functions
        function showLoading() {
            elements.resultsContainer.innerHTML = `
                <div style="text-align: center; padding: 40px;">
                    <div class="loading-spinner"></div>
                    <p style="margin-top: 16px; color: var(--text-secondary);">Searching...</p>
                </div>
            `;
        }

        function showError(message) {
            elements.resultsContainer.innerHTML = `
                <div class="empty-state">
                    <div class="empty-state-icon">⚠️</div>
                    <h3>Error</h3>
                    <p>${message}</p>
                </div>
            `;
        }

        function showEmptyState() {
            elements.resultsContainer.innerHTML = `
                <div class="empty-state">
                    <div class="empty-state-icon">🔍</div>
                    <h3>No results found</h3>
                    <p>Try adjusting your search query or filters</p>
                </div>
            `;
        }

        function renderResults(data) {
            if (!data.results || data.results.length === 0) {
                showEmptyState();
                return;
            }

            const html = data.results.map(result => {
                const favicon = ``;
                const snippet = highlightText(result.snippet || result.content?.substring(0, 200) + '...' || '', state.query);

                return `
                    <div class="result-card">
                        <div class="result-header">
                            <img src="${favicon}" alt="" class="result-favicon" onerror="this.style.display='none'">
                            ${result.title}
                            <span class="result-score">${(result.score * 100).toFixed(0)}%</span>
                        </div>
                        <div class="result-url">${result.url}</div>
                        <div class="result-snippet">${snippet}</div>
                        <div class="result-meta">
                            <span>${result.domain}</span>
                            <span>•</span>
                            <span>${formatDate(result.published_date || result.last_indexed)}</span>
                        </div>
                    </div>
                `;
            }).join('');

            elements.resultsContainer.innerHTML = html;
        }

        function trackClick(url) {
            console.log('Click tracked:', url);
            // Could send analytics to backend
        }

        // Event handlers
        async function handleSearch() {
            const query = elements.searchInput.value.trim();
            if (!query) return;

            state.query = query;
            state.filters = {
                domains: elements.domainFilter.value ? [elements.domainFilter.value] : [],
                dateStart: elements.dateFrom.value || null,
                dateEnd: elements.dateTo.value || null,
                numResults: parseInt(elements.numResults.value) || 10
            };

            // Update URL
            const params = new URLSearchParams({ q: query });
            history.pushState({ query }, '', `?${params.toString()}`);

            // Perform search
            elements.searchButton.disabled = true;
            showLoading();

            try {
                const data = await search(query, state.filters);
                renderResults(data);
            } catch (error) {
                console.error('Search error:', error);
                showError(error.message);
            } finally {
                elements.searchButton.disabled = false;
            }
        }

        function handleResetFilters() {
            elements.domainFilter.value = '';
            elements.dateFrom.value = '';
            elements.dateTo.value = '';
            elements.numResults.value = '10';
        }

        async function handleSendRequest() {
            const endpoint = elements.endpointSelect.value;
            let body;

            try {
                body = JSON.parse(elements.requestBody.value);
            } catch (error) {
                elements.responseStatus.innerHTML = '<span class="status-badge status-error">Invalid JSON</span>';
                elements.responseBody.textContent = error.message;
                return;
            }

            elements.sendRequest.disabled = true;
            elements.responseStatus.innerHTML = '<span class="status-badge">Sending...</span>';
            elements.responseBody.textContent = 'Loading...';

            const startTime = Date.now();

            try {
                const data = await apiRequest(endpoint, {
                    method: 'POST',
                    body: JSON.stringify(body)
                });

                const duration = Date.now() - startTime;
                elements.responseStatus.innerHTML = `
                    <span class="status-badge status-success">200 OK</span>
                    <span style="margin-left: 8px; font-size: 12px;">${duration}ms</span>
                `;
                elements.responseBody.textContent = JSON.stringify(data, null, 2);
            } catch (error) {
                elements.responseStatus.innerHTML = '<span class="status-badge status-error">Error</span>';
                elements.responseBody.textContent = error.message;
            } finally {
                elements.sendRequest.disabled = false;
            }
        }

        async function handleAdminLogin() {
            const apiKey = elements.adminApiKey.value.trim();
            if (!apiKey) return;

            state.adminApiKey = apiKey;
            state.apiKey = apiKey;
            localStorage.setItem('adminApiKey', apiKey);
            localStorage.setItem('apiKey', apiKey);

            try {
                // Test authentication with health check
                await apiRequest('/health');
                state.isAuthenticated = true;
                elements.adminLogin.style.display = 'none';
                elements.adminDashboard.style.display = 'block';
                loadDashboardData();
            } catch (error) {
                alert('Authentication failed: ' + error.message);
            }
        }

        async function loadDashboardData() {
            try {
                const health = await apiRequest('/health');
                document.getElementById('statDocuments').textContent = health.documents_indexed || '0';
                document.getElementById('statQueue').textContent = health.queue_depth || '0';
