                // Could add more API calls for stats
            } catch (error) {
                console.error('Dashboard load error:', error);
            }
        }

        async function handleSubmitCrawl() {
            const urls = elements.crawlUrls.value.split('\n').filter(u => u.trim());
            const maxDepth = parseInt(elements.crawlDepth.value) || 1;

            if (urls.length === 0) {
                alert('Please enter at least one URL');
                return;
            }

            try {
                const data = await apiRequest('/api/index', {
                    method: 'POST',
                    body: JSON.stringify({
                        urls: urls,
                        max_depth: maxDepth
                    })
                });

                alert(`Job submitted: ${data.job_id}`);
                elements.crawlUrls.value = '';
                loadDashboardData();
            } catch (error) {
                alert('Error: ' + error.message);
            }
        }

        function switchPage(pageName) {
            // Update navigation
            document.querySelectorAll('.nav-link').forEach(link => {
                link.classList.toggle('active', link.dataset.page === pageName);
            });

            // Update sections
            document.querySelectorAll('.section').forEach(section => {
                section.classList.remove('active');
            });

            document.getElementById(`${pageName}-section`).classList.add('active');
