            // Load data if needed
            if (pageName === 'admin' && state.isAuthenticated) {
                loadDashboardData();
            }
        }

        function toggleTheme() {
            state.theme = state.theme === 'light' ? 'dark' : 'light';
            document.documentElement.setAttribute('data-theme', state.theme);
            localStorage.setItem('theme', state.theme);
        }

        // Event listeners
        elements.searchButton.addEventListener('click', handleSearch);
        elements.searchInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') handleSearch();
        });
        elements.applyFilters.addEventListener('click', handleSearch);
        elements.resetFilters.addEventListener('click', handleResetFilters);
        elements.sendRequest.addEventListener('click', handleSendRequest);
        elements.loginButton.addEventListener('click', handleAdminLogin);
        elements.submitCrawl.addEventListener('click', handleSubmitCrawl);
        elements.themeToggle.addEventListener('click', toggleTheme);
        elements.modalClose.addEventListener('click', () => {
            elements.modal.classList.remove('active');
        });

        // Navigation
        document.querySelectorAll('.nav-link').forEach(link => {
            link.addEventListener('click', () => {
                switchPage(link.dataset.page);
            });
        });

        // Autocomplete (debounced)
        const autocomplete = debounce(async (query) => {
            if (query.length < 2) return;

            try {
                const data = await apiRequest(`/api/autocomplete?q=${encodeURIComponent(query)}`);
                // Could display suggestions dropdown
                console.log('Autocomplete suggestions:', data);
            } catch (error) {
                console.error('Autocomplete error:', error);
            }
        }, 300);

        elements.searchInput.addEventListener('input', (e) => {
            autocomplete(e.target.value);
        });

        // Initialize
        function init() {
            // Set theme
            document.documentElement.setAttribute('data-theme', state.theme);

            // Check if admin already authenticated
            if (state.adminApiKey) {
                elements.adminApiKey.value = state.adminApiKey;
            }

            // Handle URL parameters
            const params = new URLSearchParams(window.location.search);
            const queryParam = params.get('q');
            if (queryParam) {
                elements.searchInput.value = queryParam;
                handleSearch();
            }

            // Handle browser back/forward
            window.addEventListener('popstate', (event) => {
                if (event.state && event.state.query) {
                    elements.searchInput.value = event.state.query;
                    handleSearch();
                }
            });

            console.log('Application initialized');
        }

        // Start application
        init();
    </script>
